FUNCTION_BLOCK FB_Semiconductor_CVD_ShowerheadHeating
(*
====================================================================================================
  LUMINA HIGH-INTEGRITY CYBER-PHYSICAL AUTOMATION ARCHITECTURE: IEC 61131-3 SYNTHETIC BENCHMARK
  DOMAIN: 300mm SEMICONDUCTOR CHEMICAL VAPOR DEPOSITION (CVD / ALD)
  SUBSYSTEM: TRIPLE-ZONE SHOWERHEAD TEMPERATURE HOMOGENEITY & PRECURSOR PRE-HEATING BALANCE
  AUTHOR: Principal Automation Fellow & Cyber-Physical Systems Chair (Max-Persona V7)
  TARGET HARDWARE: Hard Real-Time PLC / Industrial Embedded PAC (IEC 61131-3 Compliant)
----------------------------------------------------------------------------------------------------
  PROCESS ENGINEERING SPECIFICATION:
  - Concentric 3-Zone Showerhead Distribution (Zone 1: Center, Zone 2: Middle, Zone 3: Outer Edge)
  - Precursor Delivery Line Pre-heater with Vapor Pressure Equilibrium Tracking
  - Real-Time Decoupled State-Space Matrix Model with Cross-Zone Conductive Coupling
  - Disturbance Feedforward Compensation for 13.56MHz/400kHz RF Plasma Heat Flux Deposition
  - Dynamic Mass Flow Convective Gas Cooling Load Rejection (sccm Precursor + Dilution Carrier)
  - 2oo3 (Triple Modular Redundancy) Hardware TC Sensor Voting with Graceful Degradation (1oo2/1oo1)
  - Thermomechanical Shear Stress Estimation on 300mm Faceplate (AlN / Anodized Al6061-T6)
  - Clausius-Clapeyron Condensation Margin & Precursor Thermal Pyrolysis Prevention
====================================================================================================
*)

VAR_INPUT
    bEnable                     : BOOL;     (* System master enable signal from tool host *)
    bSafetyInterlockOk          : BOOL;     (* Safety loop OK: Vacuum interlock, toxic exhaust, purge status *)
    bDepositionActive           : BOOL;     (* Precursor gas injection valve opened flag (active CVD reaction) *)
    bRecipeAbort                : BOOL;     (* Cluster tool emergency recipe cancel signal *)
    rShowerheadTempSP_degC      : REAL;     (* Recipe target setpoint for showerhead faceplate [deg C] *)
    rPrecursorTempSP_degC       : REAL;     (* Recipe target setpoint for precursor vapor line [deg C] *)
    rChamberPressure_Torr       : REAL;     (* Process chamber capacitance manometer feedback [Torr] *)
    rPrecursorFlow_sccm         : REAL;     (* Precursor mass flow controller actual feedback [sccm] *)
    rCarrierGasFlow_sccm        : REAL;     (* Carrier gas (Ar/N2/He) flow controller feedback [sccm] *)
    rRF_Power_kW                : REAL;     (* Forward plasma generator RF power into showerhead electrode [kW] *)
    rFilmTargetThickness_nm     : REAL;     (* Process recipe target deposition layer thickness [nm] *)
    arTMR_TC_Zone1              : ARRAY[1..3] OF REAL; (* Zone 1 (Center) 2oo3 Mineral-Insulated TC readings [deg C] *)
    arTMR_TC_Zone2              : ARRAY[1..3] OF REAL; (* Zone 2 (Middle) 2oo3 Mineral-Insulated TC readings [deg C] *)
    arTMR_TC_Zone3              : ARRAY[1..3] OF REAL; (* Zone 3 (Outer) 2oo3 Mineral-Insulated TC readings [deg C] *)
    arTMR_TC_Preheater          : ARRAY[1..3] OF REAL; (* Precursor line pre-heater 2oo3 TC readings [deg C] *)
    rMaxAllowedDeltaT_degC      : REAL := 0.50; (* Radial temperature uniformity acceptance criteria [deg C] *)
    rThermalSlewRate_degC_min   : REAL := 12.0; (* Faceplate maximum thermal ramp rate limit [deg C/min] *)
    rCycleTime_s                : REAL := 0.05; (* Execution task periodic scan cycle time [s] *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* Thermal homogeneity and preheat within SEMI E10 deposition tolerance *)
    bThermalRunawayTrip         : BOOL;     (* Latched fast trip: over-temperature or decouple divergence detected *)
    rHeaterPower_Zone1_kW       : REAL;     (* SCR power demand command to Zone 1 center resistive element [kW] *)
    rHeaterPower_Zone2_kW       : REAL;     (* SCR power demand command to Zone 2 middle resistive element [kW] *)
    rHeaterPower_Zone3_kW       : REAL;     (* SCR power demand command to Zone 3 outer edge resistive element [kW] *)
    rPreheaterPower_kW          : REAL;     (* SCR power demand command to precursor gas line heating jacket [kW] *)
    rThermalHomogeneity_degC    : REAL;     (* Radial temperature spread: Max(Z1..Z3) - Min(Z1..Z3) [deg C] *)
    rPrecursorMargin_degC       : REAL;     (* Margin between precursor temperature and condensation point [deg C] *)
    rFaceplateThermalStress_MPa : REAL;     (* Estimated thermo-mechanical shear stress across showerhead disk [MPa] *)
    rEstimatedGasDensity_mg_cm3 : REAL;     (* Calculated gas mixture density at showerhead injector orifice [mg/cm3] *)
    rCoolingGasBypass_Pct       : REAL;     (* Active cooling edge-purge gas valve modulation command [%] *)
    wStatusWord                 : WORD;     (* Subsystem operational telemetry bitfield [WORD] *)
    wAlarmWord                  : WORD;     (* Subsystem fault, trip, and sensor degradation register [WORD] *)
    iCurrentState               : INT;      (* Active state machine state enumeration index *)
END_VAR

VAR
    (* State Machine State Constants *)
    c_iSTATE_SAFE_OFF            : INT := 0;  (* De-energized safe standby *)
    c_iSTATE_SENSOR_VALIDATE     : INT := 10; (* 2oo3 TMR verification and sensor health audit *)
    c_iSTATE_PREHEATER_WARMUP    : INT := 20; (* Precursor line preheating to avoid condensation *)
    c_iSTATE_COORDINATED_RAMP    : INT := 30; (* S-curve multizone thermal ramping with delta-T clamping *)
    c_iSTATE_HOMOGENEITY_SOAK    : INT := 40; (* Thermal soak and cross-zone spatial equilibrium hold *)
    c_iSTATE_CVD_PROCESS_ACTIVE  : INT := 50; (* Active deposition: RF feedforward & gas cooling rejection *)
    c_iSTATE_CONTROLLED_COOLDOWN : INT := 60; (* Controlled thermal decay below oxidation/pyrolysis threshold *)
    c_iSTATE_FAULT_LOCKOUT       : INT := 99; (* Emergency trip: zero power, full safety purge *)

    (* Internal State Flags and Timers *)
    iState                      : INT := 0;
    iPrevState                  : INT := 0;
    tSoakTimer                  : TON;
    tPurgeTimer                 : TON;
    tSensorFaultDebounce        : TON;
    tFaultHoldTimer             : TON;

    (* 2oo3 Triple Modular Redundancy Internal Diagnostics *)
    arHealthy_Z1                : ARRAY[1..3] OF BOOL;
    arHealthy_Z2                : ARRAY[1..3] OF BOOL;
    arHealthy_Z3                : ARRAY[1..3] OF BOOL;
    arHealthy_Pre               : ARRAY[1..3] OF BOOL;
    iHealthyCount_Z1            : INT;
    iHealthyCount_Z2            : INT;
    iHealthyCount_Z3            : INT;
    iHealthyCount_Pre           : INT;
    rVotedTemp_Z1               : REAL;
    rVotedTemp_Z2               : REAL;
    rVotedTemp_Z3               : REAL;
    rVotedTemp_Pre              : REAL;

    (* Low-Pass Filter Accumulators (First-Order Lag Tau = 0.5s) *)
    rFiltered_Z1                : REAL := 25.0;
    rFiltered_Z2                : REAL := 25.0;
    rFiltered_Z3                : REAL := 25.0;
    rFiltered_Pre               : REAL := 25.0;
    rFilterAlpha                : REAL := 0.095; (* Discrete 1st order lag filter weight *)

    (* Trajectory Ramping Coordinates *)
    rRampedSP_Showerhead        : REAL := 25.0;
    rRampedSP_Preheater         : REAL := 25.0;
    rRampStep_degC              : REAL;

    (* Decoupled State-Space Matrix & Thermal Coefficients *)
    (* Cross-conduction matrix elements between concentric circular zones [W/deg C] *)
    c_k11                       : REAL := 14.50; (* Zone 1 self-thermal capacitance / boundary loss *)
    c_k12                       : REAL := -8.20; (* Conduction between Zone 1 (Center) and Zone 2 (Mid) *)
    c_k21                       : REAL := -8.20; (* Symmetric conduction Mid to Center *)
    c_k22                       : REAL := 22.40; (* Zone 2 combined cross-loss and heat sink factor *)
    c_k23                       : REAL := -12.10;(* Conduction between Zone 2 (Mid) and Zone 3 (Outer) *)
    c_k32                       : REAL := -12.10;(* Symmetric conduction Outer to Mid *)
    c_k33                       : REAL := 26.80; (* Zone 3 edge conduction and radiation to vacuum wall *)

    (* Plasma RF Deposition Feedforward Gains [kW heater power reduction / kW RF] *)
    c_gRF_Z1                    : REAL := 0.285; (* Center plasma density concentration *)
    c_gRF_Z2                    : REAL := 0.320; (* Mid-radius magnetic/capacitive plasma coupling *)
    c_gRF_Z3                    : REAL := 0.380; (* Edge electric field fringing & parasitic heating *)

    (* Convective Cooling Heat Transfer Load Factors [kW / (sccm * deg C)] *)
    c_gFlow_Z1                  : REAL := 0.000045; (* Direct stagnation point cooling at gas inlet center *)
    c_gFlow_Z2                  : REAL := 0.000028; (* Intermediate radial gas expansion cooling *)
    c_gFlow_Z3                  : REAL := 0.000014; (* Edge exhaust gas convective dissipation *)

    (* Closed-Loop PID / Model State Variables *)
    rErr_Z1                     : REAL;
    rErr_Z2                     : REAL;
    rErr_Z3                     : REAL;
    rErr_Pre                    : REAL;
    rInteg_Z1                   : REAL := 0.0;
    rInteg_Z2                   : REAL := 0.0;
    rInteg_Z3                   : REAL := 0.0;
    rInteg_Pre                  : REAL := 0.0;
    rPrevErr_Z1                 : REAL := 0.0;
    rPrevErr_Z2                 : REAL := 0.0;
    rPrevErr_Z3                 : REAL := 0.0;
    rPrevErr_Pre                : REAL := 0.0;
    rDeriv_Z1                   : REAL;
    rDeriv_Z2                   : REAL;
    rDeriv_Z3                   : REAL;
    rDeriv_Pre                  : REAL;

    (* Tuning Constants *)
    c_Kp_Z1                     : REAL := 0.085;
    c_Ki_Z1                     : REAL := 0.0042;
    c_Kd_Z1                     : REAL := 0.350;
    c_Kp_Z2                     : REAL := 0.110;
    c_Ki_Z2                     : REAL := 0.0055;
    c_Kd_Z2                     : REAL := 0.420;
    c_Kp_Z3                     : REAL := 0.145;
    c_Ki_Z3                     : REAL := 0.0072;
    c_Kd_Z3                     : REAL := 0.580;
    c_Kp_Pre                    : REAL := 0.065;
    c_Ki_Pre                    : REAL := 0.0035;
    c_Kd_Pre                    : REAL := 0.220;

    (* Physical & Safe Hardware Maximum Power Limits *)
    c_rMaxPwr_Z1_kW             : REAL := 3.80;  (* Zone 1 heater hardware ceiling *)
    c_rMaxPwr_Z2_kW             : REAL := 5.50;  (* Zone 2 heater hardware ceiling *)
    c_rMaxPwr_Z3_kW             : REAL := 7.50;  (* Zone 3 edge heater hardware ceiling *)
    c_rMaxPwr_Pre_kW            : REAL := 2.50;  (* Gas line heater hardware ceiling *)
    c_rMaxPermissibleTemp_degC  : REAL := 550.0; (* Hard thermal trip ceiling *)
    c_rMinPermissibleTemp_degC  : REAL := 15.0;  (* Sensor open/short circuit lower bound *)
    c_rMaxTMRDiscrepancy_degC   : REAL := 4.50;  (* 2oo3 inter-sensor divergence threshold *)

    (* Thermodynamic Physical Properties & Stress Model Constants *)
    c_rAlN_Alpha_Expansion      : REAL := 4.5E-6;(* Thermal expansion coefficient of AlN faceplate [1/K] *)
    c_rAlN_YoungsModulus_GPa    : REAL := 310.0; (* Elastic modulus of Aluminum Nitride [GPa] *)
    c_rAlN_PoissonRatio         : REAL := 0.24;  (* Poisson ratio *)
    c_rPrecursor_Antoine_A      : REAL := 7.82;  (* Precursor vapor pressure Antoine parameter A *)
    c_rPrecursor_Antoine_B      : REAL := 1820.0;(* Antoine parameter B *)
    c_rPrecursor_Antoine_C      : REAL := 215.0; (* Antoine parameter C *)
    c_rPrecursorPyrolysisMax_degC : REAL := 210.0; (* Premature chemical decomposition boundary *)
    c_rMolecularWeight_g_mol    : REAL := 176.2; (* Organometallic CVD precursor molar mass *)
    c_rUniversalGasConstant_R   : REAL := 62363.7; (* [Torr * cm3 / (mol * K)] *)

    (* Intermediate Calculation Registers *)
    rTempMin                    : REAL;
    rTempMax                    : REAL;
    rPrecursorPartialPressure_Torr : REAL;
    rPrecursorSatTemp_degC      : REAL;
    rGasTotalFlow_sccm          : REAL;
    rMeanTemp_K                 : REAL;
    rMolarVolume_cm3            : REAL;
    rFF_RF_Z1                   : REAL;
    rFF_RF_Z2                   : REAL;
    rFF_RF_Z3                   : REAL;
    rFF_Flow_Z1                 : REAL;
    rFF_Flow_Z2                 : REAL;
    rFF_Flow_Z3                 : REAL;
    rDecoupledRaw_Z1            : REAL;
    rDecoupledRaw_Z2            : REAL;
    rDecoupledRaw_Z3            : REAL;
    rDecoupledRaw_Pre           : REAL;
    rDeltaRadial_Z13            : REAL;
END_VAR

(*
====================================================================================================
  EXECUTIVE LOGIC IMPLEMENTATION
====================================================================================================
*)

(* -------------------------------------------------------------------------------------------------
   SECTION 1: SAFETY INTERLOCK AND HARD TRIPS (FAIL-SAFE HIGH PRIORITY)
------------------------------------------------------------------------------------------------- *)
IF (NOT bSafetyInterlockOk) OR bRecipeAbort THEN
    bThermalRunawayTrip := (NOT bSafetyInterlockOk) AND bEnable;
    rHeaterPower_Zone1_kW := 0.0;
    rHeaterPower_Zone2_kW := 0.0;
    rHeaterPower_Zone3_kW := 0.0;
    rPreheaterPower_kW    := 0.0;
    rCoolingGasBypass_Pct := 100.0; (* Emergency nitrogen backside flood to quench heat *)
    bSystemReady          := FALSE;
    iState                := c_iSTATE_FAULT_LOCKOUT;
    wAlarmWord.0          := TRUE;  (* Bit 0: Safety interlock violation *)
    wStatusWord.0         := FALSE; (* Clear active status *)
END_IF;

(* -------------------------------------------------------------------------------------------------
   SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) SENSOR VOTING & HEALTH AUDIT
------------------------------------------------------------------------------------------------- *)
(* Check Sensor Channel Boundaries for Zone 1 *)
arHealthy_Z1[1] := (arTMR_TC_Zone1[1] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone1[1] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z1[2] := (arTMR_TC_Zone1[2] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone1[2] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z1[3] := (arTMR_TC_Zone1[3] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone1[3] <= c_rMaxPermissibleTemp_degC);

(* Zone 1 Cross-channel Divergence Diagnostics *)
IF arHealthy_Z1[1] AND arHealthy_Z1[2] AND (ABS(arTMR_TC_Zone1[1] - arTMR_TC_Zone1[2]) > c_rMaxTMRDiscrepancy_degC) THEN
    wAlarmWord.1 := TRUE; (* Bit 1: TMR drift warning Z1 *)
END_IF;

iHealthyCount_Z1 := BOOL_TO_INT(arHealthy_Z1[1]) + BOOL_TO_INT(arHealthy_Z1[2]) + BOOL_TO_INT(arHealthy_Z1[3]);

IF iHealthyCount_Z1 = 3 THEN
    (* Standard 2oo3 Median Selection: Voted value is middle of the three *)
    IF ((arTMR_TC_Zone1[1] >= arTMR_TC_Zone1[2]) AND (arTMR_TC_Zone1[1] <= arTMR_TC_Zone1[3])) OR
       ((arTMR_TC_Zone1[1] <= arTMR_TC_Zone1[2]) AND (arTMR_TC_Zone1[1] >= arTMR_TC_Zone1[3])) THEN
        rVotedTemp_Z1 := arTMR_TC_Zone1[1];
    ELSIF ((arTMR_TC_Zone1[2] >= arTMR_TC_Zone1[1]) AND (arTMR_TC_Zone1[2] <= arTMR_TC_Zone1[3])) OR
          ((arTMR_TC_Zone1[2] <= arTMR_TC_Zone1[1]) AND (arTMR_TC_Zone1[2] >= arTMR_TC_Zone1[3])) THEN
        rVotedTemp_Z1 := arTMR_TC_Zone1[2];
    ELSE
        rVotedTemp_Z1 := arTMR_TC_Zone1[3];
    END_IF;
ELSIF iHealthyCount_Z1 = 2 THEN
    (* Graceful degradation to 1oo2 Average *)
    wAlarmWord.2 := TRUE; (* Bit 2: Zone 1 degraded 1oo2 mode *)
    IF NOT arHealthy_Z1[1] THEN
        rVotedTemp_Z1 := (arTMR_TC_Zone1[2] + arTMR_TC_Zone1[3]) * 0.5;
    ELSIF NOT arHealthy_Z1[2] THEN
        rVotedTemp_Z1 := (arTMR_TC_Zone1[1] + arTMR_TC_Zone1[3]) * 0.5;
    ELSE
        rVotedTemp_Z1 := (arTMR_TC_Zone1[1] + arTMR_TC_Zone1[2]) * 0.5;
    END_IF;
ELSIF iHealthyCount_Z1 = 1 THEN
    (* Severe degradation to single remaining channel *)
    wAlarmWord.3 := TRUE; (* Bit 3: Zone 1 single point of failure risk *)
    IF arHealthy_Z1[1] THEN rVotedTemp_Z1 := arTMR_TC_Zone1[1];
    ELSIF arHealthy_Z1[2] THEN rVotedTemp_Z1 := arTMR_TC_Zone1[2];
    ELSE rVotedTemp_Z1 := arTMR_TC_Zone1[3];
    END_IF;
ELSE
    (* Total TMR sensor failure for Zone 1 *)
    wAlarmWord.4 := TRUE; (* Bit 4: Zone 1 complete sensor loss *)
    bThermalRunawayTrip := TRUE;
    iState := c_iSTATE_FAULT_LOCKOUT;
END_IF;

(* Check Sensor Channel Boundaries for Zone 2 *)
arHealthy_Z2[1] := (arTMR_TC_Zone2[1] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone2[1] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z2[2] := (arTMR_TC_Zone2[2] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone2[2] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z2[3] := (arTMR_TC_Zone2[3] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone2[3] <= c_rMaxPermissibleTemp_degC);
iHealthyCount_Z2 := BOOL_TO_INT(arHealthy_Z2[1]) + BOOL_TO_INT(arHealthy_Z2[2]) + BOOL_TO_INT(arHealthy_Z2[3]);

IF iHealthyCount_Z2 = 3 THEN
    IF ((arTMR_TC_Zone2[1] >= arTMR_TC_Zone2[2]) AND (arTMR_TC_Zone2[1] <= arTMR_TC_Zone2[3])) OR
       ((arTMR_TC_Zone2[1] <= arTMR_TC_Zone2[2]) AND (arTMR_TC_Zone2[1] >= arTMR_TC_Zone2[3])) THEN
        rVotedTemp_Z2 := arTMR_TC_Zone2[1];
    ELSIF ((arTMR_TC_Zone2[2] >= arTMR_TC_Zone2[1]) AND (arTMR_TC_Zone2[2] <= arTMR_TC_Zone2[3])) OR
          ((arTMR_TC_Zone2[2] <= arTMR_TC_Zone2[1]) AND (arTMR_TC_Zone2[2] >= arTMR_TC_Zone2[3])) THEN
        rVotedTemp_Z2 := arTMR_TC_Zone2[2];
    ELSE
        rVotedTemp_Z2 := arTMR_TC_Zone2[3];
    END_IF;
ELSIF iHealthyCount_Z2 = 2 THEN
    wAlarmWord.5 := TRUE; (* Bit 5: Zone 2 degraded mode *)
    IF NOT arHealthy_Z2[1] THEN rVotedTemp_Z2 := (arTMR_TC_Zone2[2] + arTMR_TC_Zone2[3]) * 0.5;
    ELSIF NOT arHealthy_Z2[2] THEN rVotedTemp_Z2 := (arTMR_TC_Zone2[1] + arTMR_TC_Zone2[3]) * 0.5;
    ELSE rVotedTemp_Z2 := (arTMR_TC_Zone2[1] + arTMR_TC_Zone2[2]) * 0.5;
    END_IF;
ELSIF iHealthyCount_Z2 = 1 THEN
    IF arHealthy_Z2[1] THEN rVotedTemp_Z2 := arTMR_TC_Zone2[1];
    ELSIF arHealthy_Z2[2] THEN rVotedTemp_Z2 := arTMR_TC_Zone2[2];
    ELSE rVotedTemp_Z2 := arTMR_TC_Zone2[3];
    END_IF;
ELSE
    wAlarmWord.6 := TRUE;
    bThermalRunawayTrip := TRUE;
    iState := c_iSTATE_FAULT_LOCKOUT;
END_IF;

(* Check Sensor Channel Boundaries for Zone 3 *)
arHealthy_Z3[1] := (arTMR_TC_Zone3[1] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone3[1] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z3[2] := (arTMR_TC_Zone3[2] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone3[2] <= c_rMaxPermissibleTemp_degC);
arHealthy_Z3[3] := (arTMR_TC_Zone3[3] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Zone3[3] <= c_rMaxPermissibleTemp_degC);
iHealthyCount_Z3 := BOOL_TO_INT(arHealthy_Z3[1]) + BOOL_TO_INT(arHealthy_Z3[2]) + BOOL_TO_INT(arHealthy_Z3[3]);

IF iHealthyCount_Z3 = 3 THEN
    IF ((arTMR_TC_Zone3[1] >= arTMR_TC_Zone3[2]) AND (arTMR_TC_Zone3[1] <= arTMR_TC_Zone3[3])) OR
       ((arTMR_TC_Zone3[1] <= arTMR_TC_Zone3[2]) AND (arTMR_TC_Zone3[1] >= arTMR_TC_Zone3[3])) THEN
        rVotedTemp_Z3 := arTMR_TC_Zone3[1];
    ELSIF ((arTMR_TC_Zone3[2] >= arTMR_TC_Zone3[1]) AND (arTMR_TC_Zone3[2] <= arTMR_TC_Zone3[3])) OR
          ((arTMR_TC_Zone3[2] <= arTMR_TC_Zone3[1]) AND (arTMR_TC_Zone3[2] >= arTMR_TC_Zone3[3])) THEN
        rVotedTemp_Z3 := arTMR_TC_Zone3[2];
    ELSE
        rVotedTemp_Z3 := arTMR_TC_Zone3[3];
    END_IF;
ELSIF iHealthyCount_Z3 = 2 THEN
    wAlarmWord.7 := TRUE; (* Bit 7: Zone 3 degraded mode *)
    IF NOT arHealthy_Z3[1] THEN rVotedTemp_Z3 := (arTMR_TC_Zone3[2] + arTMR_TC_Zone3[3]) * 0.5;
    ELSIF NOT arHealthy_Z3[2] THEN rVotedTemp_Z3 := (arTMR_TC_Zone3[1] + arTMR_TC_Zone3[3]) * 0.5;
    ELSE rVotedTemp_Z3 := (arTMR_TC_Zone3[1] + arTMR_TC_Zone3[2]) * 0.5;
    END_IF;
ELSIF iHealthyCount_Z3 = 1 THEN
    IF arHealthy_Z3[1] THEN rVotedTemp_Z3 := arTMR_TC_Zone3[1];
    ELSIF arHealthy_Z3[2] THEN rVotedTemp_Z3 := arTMR_TC_Zone3[2];
    ELSE rVotedTemp_Z3 := arTMR_TC_Zone3[3];
    END_IF;
ELSE
    wAlarmWord.8 := TRUE;
    bThermalRunawayTrip := TRUE;
    iState := c_iSTATE_FAULT_LOCKOUT;
END_IF;

(* Precursor Delivery Line TMR Voting *)
arHealthy_Pre[1] := (arTMR_TC_Preheater[1] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Preheater[1] <= c_rMaxPermissibleTemp_degC);
arHealthy_Pre[2] := (arTMR_TC_Preheater[2] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Preheater[2] <= c_rMaxPermissibleTemp_degC);
arHealthy_Pre[3] := (arTMR_TC_Preheater[3] >= c_rMinPermissibleTemp_degC) AND (arTMR_TC_Preheater[3] <= c_rMaxPermissibleTemp_degC);
iHealthyCount_Pre := BOOL_TO_INT(arHealthy_Pre[1]) + BOOL_TO_INT(arHealthy_Pre[2]) + BOOL_TO_INT(arHealthy_Pre[3]);

IF iHealthyCount_Pre = 3 THEN
    IF ((arTMR_TC_Preheater[1] >= arTMR_TC_Preheater[2]) AND (arTMR_TC_Preheater[1] <= arTMR_TC_Preheater[3])) OR
       ((arTMR_TC_Preheater[1] <= arTMR_TC_Preheater[2]) AND (arTMR_TC_Preheater[1] >= arTMR_TC_Preheater[3])) THEN
        rVotedTemp_Pre := arTMR_TC_Preheater[1];
    ELSIF ((arTMR_TC_Preheater[2] >= arTMR_TC_Preheater[1]) AND (arTMR_TC_Preheater[2] <= arTMR_TC_Preheater[3])) OR
          ((arTMR_TC_Preheater[2] <= arTMR_TC_Preheater[1]) AND (arTMR_TC_Preheater[2] >= arTMR_TC_Preheater[3])) THEN
        rVotedTemp_Pre := arTMR_TC_Preheater[2];
    ELSE
        rVotedTemp_Pre := arTMR_TC_Preheater[3];
    END_IF;
ELSIF iHealthyCount_Pre >= 1 THEN
    wAlarmWord.9 := TRUE;
    IF arHealthy_Pre[1] THEN rVotedTemp_Pre := arTMR_TC_Preheater[1];
    ELSIF arHealthy_Pre[2] THEN rVotedTemp_Pre := arTMR_TC_Preheater[2];
    ELSE rVotedTemp_Pre := arTMR_TC_Preheater[3];
    END_IF;
ELSE
    wAlarmWord.10 := TRUE;
    bThermalRunawayTrip := TRUE;
    iState := c_iSTATE_FAULT_LOCKOUT;
END_IF;

(* -------------------------------------------------------------------------------------------------
   SECTION 3: SIGNAL CONDITIONING & FIRST-ORDER LAG EXPONENTIAL FILTERING
------------------------------------------------------------------------------------------------- *)
rFiltered_Z1  := rFiltered_Z1  + rFilterAlpha * (rVotedTemp_Z1  - rFiltered_Z1);
rFiltered_Z2  := rFiltered_Z2  + rFilterAlpha * (rVotedTemp_Z2  - rFiltered_Z2);
rFiltered_Z3  := rFiltered_Z3  + rFilterAlpha * (rVotedTemp_Z3  - rFiltered_Z3);
rFiltered_Pre := rFiltered_Pre + rFilterAlpha * (rVotedTemp_Pre - rFiltered_Pre);

(* Global Temperature Spread (Radial Non-Homogeneity) *)
rTempMin := MIN(rFiltered_Z1, MIN(rFiltered_Z2, rFiltered_Z3));
rTempMax := MAX(rFiltered_Z1, MAX(rFiltered_Z2, rFiltered_Z3));
rThermalHomogeneity_degC := rTempMax - rTempMin;

(* -------------------------------------------------------------------------------------------------
   SECTION 4: THERMODYNAMIC, DENSITY & FACEPLATE SHEAR STRESS METRICS
------------------------------------------------------------------------------------------------- *)
(* Precursor Condensation Margin via Inverse Antoine Equation *)
rGasTotalFlow_sccm := MAX(1.0, rPrecursorFlow_sccm + rCarrierGasFlow_sccm);
rPrecursorPartialPressure_Torr := rChamberPressure_Torr * (rPrecursorFlow_sccm / rGasTotalFlow_sccm);

IF rPrecursorPartialPressure_Torr > 0.001 THEN
    (* T_sat = B / (A - log10(P)) - C *)
    rPrecursorSatTemp_degC := (c_rPrecursor_Antoine_B / MAX(0.1, (c_rPrecursor_Antoine_A - (LN(rPrecursorPartialPressure_Torr) / 2.302585)))) - c_rPrecursor_Antoine_C;
    rPrecursorMargin_degC := rFiltered_Pre - rPrecursorSatTemp_degC;
ELSE
    rPrecursorMargin_degC := 99.9;
END_IF;

(* Anti-condensation and Anti-pyrolysis Alarms *)
IF (rPrecursorMargin_degC < 15.0) AND bDepositionActive THEN
    wAlarmWord.11 := TRUE; (* Bit 11: Precursor condensation imminent risk *)
END_IF;

IF rFiltered_Pre > c_rPrecursorPyrolysisMax_degC THEN
    wAlarmWord.12 := TRUE; (* Bit 12: Premature precursor thermal breakdown / clogging *)
END_IF;

(* Real-Time Gas Density Estimate using Ideal Gas Equation (P*MW / R*T) *)
rMeanTemp_K := ((rFiltered_Z1 + rFiltered_Z2 + rFiltered_Z3) / 3.0) + 273.15;
IF rMeanTemp_K > 200.0 THEN
    rEstimatedGasDensity_mg_cm3 := (rChamberPressure_Torr * c_rMolecularWeight_g_mol * 1000.0) / (c_rUniversalGasConstant_R * rMeanTemp_K);
ELSE
    rEstimatedGasDensity_mg_cm3 := 0.0;
END_IF;

(* Thermomechanical Shear Stress on 300mm Ceramic / Metal Faceplate *)
(* Stress sigma = E * alpha * DeltaT_radial / (2 * (1 - nu)) *)
rDeltaRadial_Z13 := ABS(rFiltered_Z1 - rFiltered_Z3);
rFaceplateThermalStress_MPa := (c_rAlN_YoungsModulus_GPa * 1000.0 * c_rAlN_Alpha_Expansion * rDeltaRadial_Z13) / (2.0 * (1.0 - c_rAlN_PoissonRatio));

IF rFaceplateThermalStress_MPa > 120.0 THEN
    wAlarmWord.13 := TRUE; (* Bit 13: Faceplate mechanical shear stress threshold exceeded *)
END_IF;

(* -------------------------------------------------------------------------------------------------
   SECTION 5: SUPERVISORY FINITE STATE MACHINE (CASE iState)
------------------------------------------------------------------------------------------------- *)
CASE iState OF

    c_iSTATE_SAFE_OFF: (* 0: System Idle / De-energized Safe State *)
        bSystemReady                := FALSE;
        rHeaterPower_Zone1_kW       := 0.0;
        rHeaterPower_Zone2_kW       := 0.0;
        rHeaterPower_Zone3_kW       := 0.0;
        rPreheaterPower_kW          := 0.0;
        rCoolingGasBypass_Pct       := 0.0;
        rInteg_Z1                   := 0.0;
        rInteg_Z2                   := 0.0;
        rInteg_Z3                   := 0.0;
        rInteg_Pre                  := 0.0;
        rRampedSP_Showerhead        := rFiltered_Z2;
        rRampedSP_Preheater         := rFiltered_Pre;
        wStatusWord                 := 16#0000;

        IF bEnable AND bSafetyInterlockOk THEN
            iState := c_iSTATE_SENSOR_VALIDATE;
        END_IF;

    c_iSTATE_SENSOR_VALIDATE: (* 10: TMR Sensor Audit and Diagnostic Check *)
        wStatusWord.1 := TRUE; (* Validating sensors *)
        IF (iHealthyCount_Z1 >= 2) AND (iHealthyCount_Z2 >= 2) AND (iHealthyCount_Z3 >= 2) AND (iHealthyCount_Pre >= 2) THEN
            rRampedSP_Showerhead := (rFiltered_Z1 + rFiltered_Z2 + rFiltered_Z3) / 3.0;
            rRampedSP_Preheater  := rFiltered_Pre;
            iState := c_iSTATE_PREHEATER_WARMUP;
        ELSE
            iState := c_iSTATE_FAULT_LOCKOUT;
        END_IF;

    c_iSTATE_PREHEATER_WARMUP: (* 20: Ramp precursor delivery line to avoid condensation spots *)
        wStatusWord.2 := TRUE; (* Preheater warming *)
        (* Slew preheater setpoint *)
        rRampStep_degC := (rThermalSlewRate_degC_min / 60.0) * rCycleTime_s;
        IF rRampedSP_Preheater < rPrecursorTempSP_degC THEN
            rRampedSP_Preheater := MIN(rPrecursorTempSP_degC, rRampedSP_Preheater + rRampStep_degC);
        ELSIF rRampedSP_Preheater > rPrecursorTempSP_degC THEN
            rRampedSP_Preheater := MAX(rPrecursorTempSP_degC, rRampedSP_Preheater - rRampStep_degC);
        END_IF;

        (* Check if preheater reached operational envelope *)
        IF ABS(rFiltered_Pre - rPrecursorTempSP_degC) <= 1.5 THEN
            iState := c_iSTATE_COORDINATED_RAMP;
        END_IF;

        IF NOT bEnable THEN
            iState := c_iSTATE_CONTROLLED_COOLDOWN;
        END_IF;

    c_iSTATE_COORDINATED_RAMP: (* 30: Multizone Coordinated Thermal Ramping *)
        wStatusWord.3 := TRUE; (* Coordinated ramp active *)
        rRampStep_degC := (rThermalSlewRate_degC_min / 60.0) * rCycleTime_s;

        (* Advance showerhead ramp profile *)
        IF rRampedSP_Showerhead < rShowerheadTempSP_degC THEN
            rRampedSP_Showerhead := MIN(rShowerheadTempSP_degC, rRampedSP_Showerhead + rRampStep_degC);
        ELSIF rRampedSP_Showerhead > rShowerheadTempSP_degC THEN
            rRampedSP_Showerhead := MAX(rShowerheadTempSP_degC, rRampedSP_Showerhead - rRampStep_degC);
        END_IF;

        (* Maintain preheater tracking *)
        IF rRampedSP_Preheater < rPrecursorTempSP_degC THEN
            rRampedSP_Preheater := MIN(rPrecursorTempSP_degC, rRampedSP_Preheater + rRampStep_degC);
        END_IF;

        (* Transition to soak when setpoint is within 1.0 deg C *)
        IF (ABS(rFiltered_Z1 - rShowerheadTempSP_degC) < 1.0) AND
           (ABS(rFiltered_Z2 - rShowerheadTempSP_degC) < 1.0) AND
           (ABS(rFiltered_Z3 - rShowerheadTempSP_degC) < 1.0) THEN
            tSoakTimer(IN := FALSE);
            iState := c_iSTATE_HOMOGENEITY_SOAK;
        END_IF;

        IF NOT bEnable THEN
            iState := c_iSTATE_CONTROLLED_COOLDOWN;
        END_IF;

    c_iSTATE_HOMOGENEITY_SOAK: (* 40: Thermal Equilibrium & Spatial Homogeneity Soak *)
        wStatusWord.4 := TRUE; (* Homogeneity soak active *)
        rRampedSP_Showerhead := rShowerheadTempSP_degC;
        rRampedSP_Preheater  := rPrecursorTempSP_degC;

        (* Verify SEMI thermal equilibrium criteria across 300mm plate *)
        IF (rThermalHomogeneity_degC <= rMaxAllowedDeltaT_degC) AND
           (ABS(rFiltered_Pre - rPrecursorTempSP_degC) <= 1.0) THEN
            tSoakTimer(IN := TRUE, PT := T#15S);
            IF tSoakTimer.Q THEN
                bSystemReady  := TRUE;
                wStatusWord.5 := TRUE; (* Thermal ready flag *)
                IF bDepositionActive THEN
                    iState := c_iSTATE_CVD_PROCESS_ACTIVE;
                END_IF;
            END_IF;
        ELSE
            tSoakTimer(IN := FALSE);
            bSystemReady := FALSE;
        END_IF;

        IF NOT bEnable THEN
            iState := c_iSTATE_CONTROLLED_COOLDOWN;
        END_IF;

    c_iSTATE_CVD_PROCESS_ACTIVE: (* 50: Deposition Phase with RF and Gas Feedforward Compensation *)
        wStatusWord.6 := TRUE; (* CVD processing active *)
        rRampedSP_Showerhead := rShowerheadTempSP_degC;
        rRampedSP_Preheater  := rPrecursorTempSP_degC;
        bSystemReady         := (rThermalHomogeneity_degC <= (rMaxAllowedDeltaT_degC * 1.25));

        (* Edge purge cooling trim for severe high RF power scenarios *)
        IF (rFiltered_Z3 - rShowerheadTempSP_degC) > 1.2 THEN
            rCoolingGasBypass_Pct := MIN(80.0, (rFiltered_Z3 - rShowerheadTempSP_degC) * 25.0);
        ELSE
            rCoolingGasBypass_Pct := 0.0;
        END_IF;

        (* On recipe completion or gas shutoff, return to soak *)
        IF NOT bDepositionActive THEN
            bSystemReady := FALSE;
            iState := c_iSTATE_HOMOGENEITY_SOAK;
        END_IF;

        IF NOT bEnable THEN
            iState := c_iSTATE_CONTROLLED_COOLDOWN;
        END_IF;

    c_iSTATE_CONTROLLED_COOLDOWN: (* 60: Controlled thermal ramp-down *)
        wStatusWord.7 := TRUE; (* Cooling down *)
        bSystemReady  := FALSE;
        rRampStep_degC := (rThermalSlewRate_degC_min / 60.0) * rCycleTime_s;

        IF rRampedSP_Showerhead > 40.0 THEN
            rRampedSP_Showerhead := rRampedSP_Showerhead - rRampStep_degC;
        END_IF;
        IF rRampedSP_Preheater > 35.0 THEN
            rRampedSP_Preheater := rRampedSP_Preheater - rRampStep_degC;
        END_IF;

        IF (rFiltered_Z1 <= 45.0) AND (rFiltered_Z3 <= 45.0) AND (rFiltered_Pre <= 40.0) THEN
            iState := c_iSTATE_SAFE_OFF;
        END_IF;

    c_iSTATE_FAULT_LOCKOUT: (* 99: Latched Emergency Isolation *)
        bSystemReady          := FALSE;
        rHeaterPower_Zone1_kW := 0.0;
        rHeaterPower_Zone2_kW := 0.0;
        rHeaterPower_Zone3_kW := 0.0;
        rPreheaterPower_kW    := 0.0;
        rCoolingGasBypass_Pct := 100.0; (* Full cooling assist *)
        wStatusWord.15        := TRUE;  (* Fault lockout bit *)

        (* Unlatch condition: master enable toggled low, interlock restored, temperatures safe *)
        IF (NOT bEnable) AND bSafetyInterlockOk AND (NOT bThermalRunawayTrip) THEN
            iState := c_iSTATE_SAFE_OFF;
        END_IF;

ELSE
    iState := c_iSTATE_SAFE_OFF;
END_CASE;

iCurrentState := iState;

(* -------------------------------------------------------------------------------------------------
   SECTION 6: DECOUPLED STATE-SPACE & DISTURBANCE FEEDFORWARD MPC ENGINE
------------------------------------------------------------------------------------------------- *)
IF (iState >= c_iSTATE_PREHEATER_WARMUP) AND (iState <= c_iSTATE_CVD_PROCESS_ACTIVE) THEN

    (* Calculate Tracking Errors *)
    rErr_Z1  := rRampedSP_Showerhead - rFiltered_Z1;
    rErr_Z2  := rRampedSP_Showerhead - rFiltered_Z2;
    rErr_Z3  := rRampedSP_Showerhead - rFiltered_Z3;
    rErr_Pre := rRampedSP_Preheater  - rFiltered_Pre;

    (* Anti-Reset Windup Integration *)
    rInteg_Z1  := LIMIT(-1.5, rInteg_Z1  + (rErr_Z1  * rCycleTime_s), 1.5);
    rInteg_Z2  := LIMIT(-2.0, rInteg_Z2  + (rErr_Z2  * rCycleTime_s), 2.0);
    rInteg_Z3  := LIMIT(-3.0, rInteg_Z3  + (rErr_Z3  * rCycleTime_s), 3.0);
    rInteg_Pre := LIMIT(-1.0, rInteg_Pre + (rErr_Pre * rCycleTime_s), 1.0);

    (* Numerical Derivatives *)
    rDeriv_Z1  := (rErr_Z1  - rPrevErr_Z1)  / rCycleTime_s;
    rDeriv_Z2  := (rErr_Z2  - rPrevErr_Z2)  / rCycleTime_s;
    rDeriv_Z3  := (rErr_Z3  - rPrevErr_Z3)  / rCycleTime_s;
    rDeriv_Pre := (rErr_Pre - rPrevErr_Pre) / rCycleTime_s;

    rPrevErr_Z1  := rErr_Z1;
    rPrevErr_Z2  := rErr_Z2;
    rPrevErr_Z3  := rErr_Z3;
    rPrevErr_Pre := rErr_Pre;

    (* Disturbance Feedforward Computations *)
    (* Plasma RF direct thermal power deposition into showerhead faceplate *)
    rFF_RF_Z1 := c_gRF_Z1 * rRF_Power_kW;
    rFF_RF_Z2 := c_gRF_Z2 * rRF_Power_kW;
    rFF_RF_Z3 := c_gRF_Z3 * rRF_Power_kW;

    (* Convective mass flow thermal cooling load compensation *)
    rFF_Flow_Z1 := c_gFlow_Z1 * rGasTotalFlow_sccm * (rFiltered_Z1 - rFiltered_Pre);
    rFF_Flow_Z2 := c_gFlow_Z2 * rGasTotalFlow_sccm * (rFiltered_Z2 - rFiltered_Pre);
    rFF_Flow_Z3 := c_gFlow_Z3 * rGasTotalFlow_sccm * (rFiltered_Z3 - rFiltered_Pre);

    (* Decoupled Cross-Zone Conductive Matrix Balancing *)
    (* Invert steady-state conduction coupling to eliminate inter-zone thermal crosstalk *)
    rDecoupledRaw_Z1 := (c_Kp_Z1 * rErr_Z1) + (c_Ki_Z1 * rInteg_Z1) + (c_Kd_Z1 * rDeriv_Z1)
                        - rFF_RF_Z1 + rFF_Flow_Z1
                        + ((c_k12 / c_k11) * (rFiltered_Z1 - rFiltered_Z2) * 0.05);

    rDecoupledRaw_Z2 := (c_Kp_Z2 * rErr_Z2) + (c_Ki_Z2 * rInteg_Z2) + (c_Kd_Z2 * rDeriv_Z2)
                        - rFF_RF_Z2 + rFF_Flow_Z2
                        + ((c_k21 / c_k22) * (rFiltered_Z2 - rFiltered_Z1) * 0.05)
                        + ((c_k23 / c_k22) * (rFiltered_Z2 - rFiltered_Z3) * 0.05);

    rDecoupledRaw_Z3 := (c_Kp_Z3 * rErr_Z3) + (c_Ki_Z3 * rInteg_Z3) + (c_Kd_Z3 * rDeriv_Z3)
                        - rFF_RF_Z3 + rFF_Flow_Z3
                        + ((c_k32 / c_k33) * (rFiltered_Z3 - rFiltered_Z2) * 0.05);

    rDecoupledRaw_Pre := (c_Kp_Pre * rErr_Pre) + (c_Ki_Pre * rInteg_Pre) + (c_Kd_Pre * rDeriv_Pre);

    (* Clamp Actuator Demands to Physical Ratings *)
    rHeaterPower_Zone1_kW := LIMIT(0.0, rDecoupledRaw_Z1, c_rMaxPwr_Z1_kW);
    rHeaterPower_Zone2_kW := LIMIT(0.0, rDecoupledRaw_Z2, c_rMaxPwr_Z2_kW);
    rHeaterPower_Zone3_kW := LIMIT(0.0, rDecoupledRaw_Z3, c_rMaxPwr_Z3_kW);
    rPreheaterPower_kW    := LIMIT(0.0, rDecoupledRaw_Pre, c_rMaxPwr_Pre_kW);

ELSIF (iState = c_iSTATE_CONTROLLED_COOLDOWN) THEN
    (* Passive and controlled heat decay *)
    rHeaterPower_Zone1_kW := 0.0;
    rHeaterPower_Zone2_kW := 0.0;
    rHeaterPower_Zone3_kW := 0.0;
    rPreheaterPower_kW    := 0.0;
    rCoolingGasBypass_Pct := 15.0;
ELSE
    rHeaterPower_Zone1_kW := 0.0;
    rHeaterPower_Zone2_kW := 0.0;
    rHeaterPower_Zone3_kW := 0.0;
    rPreheaterPower_kW    := 0.0;
END_IF;

(* Over-temperature latch trip condition *)
IF (rFiltered_Z1 > c_rMaxPermissibleTemp_degC) OR
   (rFiltered_Z2 > c_rMaxPermissibleTemp_degC) OR
   (rFiltered_Z3 > c_rMaxPermissibleTemp_degC) OR
   (rFiltered_Pre > c_rPrecursorPyrolysisMax_degC + 15.0) THEN
    bThermalRunawayTrip := TRUE;
    wAlarmWord.14 := TRUE; (* Bit 14: Over-temperature runaway trip *)
    iState := c_iSTATE_FAULT_LOCKOUT;
END_IF;

END_FUNCTION_BLOCK
